   216	 * xmlFuzzWriteInt:
   217	 * @out:  output file
   218	 * @v:  integer to write
   219	 * @size:  size of integer in bytes
   220	 *
   221	 * Write an integer to the fuzz data.
   222	 */
   223	void
   224	xmlFuzzWriteInt(FILE *out, size_t v, int size) {
   225	    int shift;
   226	
   227	    while (size > (int) sizeof(size_t)) {
   228	        putc(0, out);
   229	        size--;
   230	    }
   231	
   232	    shift = size * 8;
   233	    while (shift > 0) {
   234	        shift -= 8;
   235	        putc((v >> shift) & 255, out);
   236	    }
   237	}
