   239	/**
   240	 * xmlFuzzReadInt:
   241	 * @size:  size of integer in bytes
   242	 *
   243	 * Read an integer from the fuzz data.
   244	 */
   245	size_t
   246	xmlFuzzReadInt(int size) {
   247	    size_t ret = 0;
   248	
   249	    while ((size > 0) && (fuzzData.remaining > 0)) {
   250	        unsigned char c = (unsigned char) *fuzzData.ptr++;
   251	        fuzzData.remaining--;
   252	        ret = (ret << 8) | c;
   253	        size--;
   254	    }
   255	
   256	    return ret;
   257	}
