   307	/**
   308	 * xmlFuzzReadString:
   309	 * @size:  size of string in bytes
   310	 *
   311	 * Read a random-length string from the fuzz data.
   312	 *
   313	 * The format is similar to libFuzzer's FuzzedDataProvider but treats
   314	 * backslash followed by newline as end of string. This makes the fuzz data
   315	 * more readable. A backslash character is escaped with another backslash.
   316	 *
   317	 * Returns a zero-terminated string or NULL if the fuzz data is exhausted.
   318	 */
   319	const char *
   320	xmlFuzzReadString(size_t *size) {
   321	    const char *out = fuzzData.outPtr;
   322	
   323	    while (fuzzData.remaining > 0) {
   324	        int c = *fuzzData.ptr++;
   325	        fuzzData.remaining--;
   326	
   327	        if ((c == '\\') && (fuzzData.remaining > 0)) {
   328	            int c2 = *fuzzData.ptr;
   329	
   330	            if (c2 == '\n') {
   331	                fuzzData.ptr++;
   332	                fuzzData.remaining--;
   333	                if (size != NULL)
   334	                    *size = fuzzData.outPtr - out;
   335	                *fuzzData.outPtr++ = '\0';
   336	                return(out);
   337	            }
   338	            if (c2 == '\\') {
   339	                fuzzData.ptr++;
   340	                fuzzData.remaining--;
   341	            }
   342	        }
   343	
   344	        *fuzzData.outPtr++ = c;
   345	    }
   346	
   347	    if (fuzzData.outPtr > out) {
   348	        if (size != NULL)
   349	            *size = fuzzData.outPtr - out;
   350	        *fuzzData.outPtr++ = '\0';
   351	        return(out);
   352	    }
   353	
   354	    if (size != NULL)
   355	        *size = 0;
   356	    return(NULL);
   357	}
