   359	/**
   360	 * xmlFuzzReadEntities:
   361	 *
   362	 * Read entities like the main XML file, external DTDs, external parsed
   363	 * entities from fuzz data.
   364	 */
   365	void
   366	xmlFuzzReadEntities(void) {
   367	    size_t num = 0;
   368	
   369	    while (1) {
   370	        const char *url, *entity;
   371	        size_t urlSize, entitySize;
   372	        xmlFuzzEntityInfo *entityInfo;
   373	
   374	        url = xmlFuzzReadString(&urlSize);
   375	        if (url == NULL) break;
   376	
   377	        entity = xmlFuzzReadString(&entitySize);
   378	        if (entity == NULL) break;
   379	
   380	        /*
   381	         * Cap URL size to avoid quadratic behavior when generating
   382	         * error messages or looking up entities.
   383	         */
   384	        if (urlSize < 50 &&
   385	            xmlHashLookup(fuzzData.entities, (xmlChar *)url) == NULL) {
   386	            entityInfo = xmlMalloc(sizeof(xmlFuzzEntityInfo));
   387	            if (entityInfo == NULL)
   388	                break;
   389	            entityInfo->data = entity;
   390	            entityInfo->size = entitySize;
   391	
   392	            xmlHashAddEntry(fuzzData.entities, (xmlChar *)url, entityInfo);
   393	
   394	            if (num == 0) {
   395	                fuzzData.mainUrl = url;
   396	                fuzzData.mainEntity = entityInfo;
   397	            } else if (num == 1) {
   398	                fuzzData.secondaryUrl = url;
   399	                fuzzData.secondaryEntity = entityInfo;
   400	            }
   401	
   402	            num++;
   403	        }
   404	    }
   405	}
